insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Asistente de Ventas', 'Brindar soporte administrativo, operativo y logístico al equipo de ventas, asegurando una atención oportuna y eficiente a los clientes, la correcta gestión de órdenes de instalación, facturación, cotizaciones y seguimiento de procesos, con el fin de contribuir al cumplimiento de los objetivos comerciales de la empresa y a la satisfacción del cliente.', 'Bachiller, Perito en Administración de Empresas. 1 año en puesto similar. Manejo de herramientas ofimáticas (Excel, Word, correo electrónico). Buenas relaciones humanas, vocación de servicio. Organizada y capaz de manejar el tiempo efectivamente.', 'ACCISA-01', 'ACCISA', 'Ventas', 'Comercial', 'Oficina principal de Accesorios Ilimitados S.A.', 'Allan Hernández', 'Operativo', 'Q4,050.00 + Comisiones', $json${"no_supervisa": "Ninguna", "posiciones_supervisa": "Ninguna", "funciones": [{"categoria": "Atención a clientes", "funcion": "Preparar, enviar cotizaciones y darles su debido seguimiento.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Atención a clientes", "funcion": "Atender los correos que se reciban de clientes en forma oportuna.", "frecuencia": "Diario", "tiempo": "0.30"}, {"categoria": "Atención a clientes", "funcion": "Atender llamadas y mensajes del celular de Ventas y en oficina.", "frecuencia": "Diario", "tiempo": "0.20"}, {"categoria": "Atención a clientes", "funcion": "Toma de pedidos y colocar órdenes de venta en sistema.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Atención a clientes", "funcion": "Atender a clientes que visitan la sala de ventas para compras o cotizaciones", "frecuencia": "Diario", "tiempo": "0.30"}, {"categoria": "Atención a clientes", "funcion": "Resolver dudas y/o situaciones relacionadas con entregas y recolecciones con los clientes.", "frecuencia": "Diario", "tiempo": "0.30"}, {"categoria": "Atención a clientes", "funcion": "Promociones: control y reporte, elaboración de cartas de entrega, coordinar autofacturación respectiva.", "frecuencia": "Diario", "tiempo": "0.10"}, {"categoria": "Facturación", "funcion": "Revisión de envíos que se trasladan a bodega para facturar.", "frecuencia": "Diario", "tiempo": "0.30"}, {"categoria": "Facturación", "funcion": "Informar a Asesores de Ventas y/o Gerente para las cotizaciones respectivas.", "frecuencia": "Diario", "tiempo": "0.30"}, {"categoria": "Facturación", "funcion": "Canalizar las facturas para su debida entrega.", "frecuencia": "Diario", "tiempo": "0.20"}, {"categoria": "Facturación", "funcion": "Conocer los detalles de fechas y procesos de facturación de las diferentes agencias para no tener contratiempos.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Facturación", "funcion": "Dar asistencia a Asesores de Ventas", "frecuencia": "Diario", "tiempo": "0.20"}, {"categoria": "Coordinación de Operaciones", "funcion": "Coordinar entregas de material y equipos con Bodega diariamente para que las Operaciones fluyan sin problemas y no se retrasen los procesos.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Coordinación de Operaciones", "funcion": "Dar seguimiento a proveedores y clientes para coordinación de recolección de equipo con Bodega", "frecuencia": "Diario", "tiempo": "0.30"}, {"categoria": "Coordinación de Operaciones", "funcion": "Dar seguimiento a cortes realizados con Bodega para poder proceder a facturación en forma oportuna.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Coordinación de Operaciones", "funcion": "Verificar horarios de recepción/entrega de materiales con clientes para evitar visitas infructuosas", "frecuencia": "Diario", "tiempo": "0.30"}, {"categoria": "Asistencia al Jefe inmediato", "funcion": "Brindar soporte en agencias automotrices y atender clientes en sala. Realizar cotizaciones y llamadas de seguimiento a prospectos.", "frecuencia": "Diario", "tiempo": "0.15"}, {"categoria": "Asistencia al Jefe inmediato", "funcion": "Coordinar instalaciones cuando el jefe inmediato no se encuentre disponible. Monitorear a los instaladores y dar seguimiento a los trabajos en proceso.", "frecuencia": "Diario", "tiempo": "1 hora"}, {"categoria": "Asistencia al Jefe inmediato", "funcion": "Llevar un control de facturas correspondiente a proveedor Canella", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Asistencia al Jefe inmediato", "funcion": "Dar soporte al Supervisor Comercial y Asesores Comerciales según se requiera.", "frecuencia": "Diario", "tiempo": "0.15"}, {"categoria": "Asistencia al Jefe inmediato", "funcion": "Asistir dudas de precios, estilos para vendedores de Excel Motors", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Asistencia al Jefe inmediato", "funcion": "Mantener informado al Supervisor Comercial de las actividades realizadas y pendientes.", "frecuencia": "Diario", "tiempo": "0.20"}, {"categoria": "Varios", "funcion": "Salir en moto cuando sea necesario para entrega de documentos, apoyo a instalaciones o gestiones en campo", "frecuencia": "Semanal", "tiempo": "0.10"}, {"categoria": "Varios", "funcion": "Colaborar en la ejecución y control de inventarios, así como en la implementación de promociones.", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "Varios", "funcion": "Crear catálogos digitales y material de apoyo para ventas", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "Varios", "funcion": "Coordinar la captura de fotografías y videos durante las instalaciones, procurando resaltar la calidad del trabajo y los productos.", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "Varios", "funcion": "Grabar contenido audiovisual en las instalaciones de la empresa, sucursales o donde se desarrollen", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "Varios", "funcion": "Enviar oportunamente los videos y fotografías al área responsable (Mercadeo, Ventas o Gerencia) para su edición, publicación o difusión.", "frecuencia": "Eventualmente", "tiempo": ""}], "indicadores": [{"indicador": "Cantidad de facturas correctas", "resultado_esperado": "Lograr un ---% de facturas sin errores."}, {"indicador": "Satisfacción de clientes internos y externos", "resultado_esperado": "95% NPS positivo"}], "inversion_actividades": "100% ACCISA", "nivel_iniciativa": "Frecuente: Todas las tareas, salvo las variaciones menores, son analizadas por el supervisor. Varias veces al día: Esto para informar o recibir asesoría y/o asignaciones. Seguir métodos, procedimientos establecidos.", "toma_decisiones": "Bajo: Tiene autoridad para tomar decisiones en su puesto que lo ayuden a desarrollar mejor su trabajo con autorización de su líder inmediato.", "riesgos": "1. No conocer el precio o los datos de facturación, al hacer las facturaciones o conocimiento del producto.\n2. Facturar al cliente montos equivocados", "manejo_activos": "Acceso a programas de Computadora (Software, Internet, Data Crédito, entre otros)", "equipos_trabajo": "Escritorio, silla. Computadora desktop, UPS. Engrapadora, lapicero, sacabocados, tapera, sellos, marcadores.", "equipos_seguridad": "Maneja información confidencial como ventas y base de datos de clientes. Sistema/Internet", "relaciones_internas": [{"departamento": "Gerencia/Gerencia General", "frecuencia": "Semanal", "proposito": "Autofacturación, reportes"}, {"departamento": "Contabilidad/Cobros", "frecuencia": "Diaria", "proposito": "Temas de facturación"}, {"departamento": "Operaciones/Bodega", "frecuencia": "Diaria", "proposito": "Temas acerca de los cortes"}, {"departamento": "Ventas/Asesores", "frecuencia": "Diaria", "proposito": "Temas de facturación"}, {"departamento": "Recepción", "frecuencia": "Diaria", "proposito": "Entrega de facturas para rutas"}], "relaciones_externas": [{"persona": "Clientes/Doctores", "frecuencia": "Diario", "proposito": "Facturas, cortes."}, {"persona": "Hospitales", "frecuencia": "Semanal", "proposito": "Requerimiento de información"}], "condiciones_trabajo": "El puesto se desenvuelve en un ambiente de oficina. Su ubicación física es la oficina instalada en la capital, donde se encuentra el centro de operaciones. En cuanto a las condiciones ambientales en donde se desarrolla el puesto, son normales.", "esfuerzo_fisico_mental": "El nivel de esfuerzo físico que este puesto requiere es bajo, debido a que las tareas que realiza no requieren de un esfuerzo físico adicional o extremo que lleven a la fatiga. Requiere de alta concentración.", "perfil": {"edad": "18+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "1 año en puesto similar", "formacion_academica": "Bachiller, Perito en Administración de Empresas", "formacion_complementaria": "N/A", "conocimientos_basicos": "Manejo de herramientas ofimáticas (Excel, Word, correo electrónico)", "habilidades_especificas": "Buenas relaciones humanas, vocación de servicio - requiere presencia física en la empresa. Organizada y capaz de manejar el tiempo efectivamente.", "conocimientos_informaticos": "Windows: Normal. Microsoft Office: Alto. Otras: Internet y Correo electrónico", "sistemas_especializados": "SAP no indispensable", "beneficios": "A definir por la empresa", "se_requiere_viajar": "No", "se_requiere_vehiculo": "No", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, compromiso, respeto y liderazgo"}, "competencias_generales": [{"competencia": "Compromiso", "grado": "A"}, {"competencia": "Capacidad de aprendizaje", "grado": "B"}, {"competencia": "Integridad", "grado": "C"}, {"competencia": "Perseverancia en la Consecución de objetivos", "grado": "B"}, {"competencia": "Proactividad", "grado": "A"}, {"competencia": "Flexibilidad y adaptación a los cambios", "grado": "D"}], "competencias_especificas": [{"competencia": "Capacidad de Planificación y Organización", "grado": "A"}, {"competencia": "Trabajo en equipo", "grado": "A"}, {"competencia": "Profundidad en el conocimiento de los productos", "grado": "A"}, {"competencia": "Influencia y negociación", "grado": "A"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente Financiero", "fecha_elaboracion": "2025-07-15", "fecha_revision": "2025-07-15", "version": "Rev. 15.07.2025 — Ref. ACCISA-01"}$json$::jsonb)
