insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Ejecutivo De Atención Al Cliente', 'Bajo la supervisión del Supervisor de Ventas, gestiona el ciclo de venta y atención al cliente desde la prospección y asesoría hasta el cobro, seguimiento postventa y entrega del vehículo, asegurando órdenes de trabajo claras, comunicación oportuna con taller, caja y bodega, seguimiento a clientes de crédito y recuperación de oportunidades comerciales en sala, campo, teléfono y medios digitales.', 'Graduado de nivel diversificado en Perito Contador, Bachiller en Ciencias y Letras, Bachiller en Computación, Perito en Administración o carrera afín. 2 años en puesto similar. Habilidad para negociar y cerrar ventas de manera efectiva. Capacidad para resolver consultas, objeciones y reclamos de manera efectiva.', 'ACCISA-005', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Allan Hernández', 'Administrativo / Operativo', 'Q4,050.00 Base + Comisiones', $json${"no_supervisa": "0", "posiciones_supervisa": "", "funciones": [{"categoria": "Atención y Asesoría Comercial", "funcion": "Realizar ventas de accesorios para vehículos.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Atención y Asesoría Comercial", "funcion": "Asesorar a los clientes en la selección y compra de accesorios adecuados para su vehículo.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Atención y Asesoría Comercial", "funcion": "Atender las llamadas de planta que ingresen durante la jornada.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Atención y Asesoría Comercial", "funcion": "Atender y dar seguimiento a clientes provenientes de redes sociales mediante el sistema Respon.de.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Atención y Asesoría Comercial", "funcion": "Procurar una experiencia agradable, acompañando al cliente al pago y al área de espera y ofreciéndole una bebida.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Atención y Asesoría Comercial", "funcion": "Recibir los vehículos que ingresan para la instalación de accesorios, validar y llenar hoja de recepción, detallando rayones, golpes u otros que cuente el vehículo al momento de recibirlo para ingreso a taller", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Atención y Asesoría Comercial", "funcion": "Elaborar la orden de trabajo, detallando los productos y servicios solicitados por el cliente.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Atención y Asesoría Comercial", "funcion": "Trasladar el vehículo al área de taller y entregar la orden de trabajo al responsable.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Atención y Asesoría Comercial", "funcion": "Dar seguimiento al proceso de instalación y a cualquier requerimiento relacionado con el servicio.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Atención y Asesoría Comercial", "funcion": "Cumplir los indicadores y metas mensuales de ventas definidos por la Gerencia Comercial, promoviendo una atención al cliente de excelencia y el cierre efectivo de negocios.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Atención y Asesoría Comercial", "funcion": "Recibir el vehículo al finalizar la instalación, verificar el servicio y entregarlo al cliente.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Clientes", "funcion": "Realizar visitas de campo a clientes de talleres, agencias y clientes individuales en el día asignado.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Clientes", "funcion": "Contactar de forma constante a clientes antiguos para generar nuevas oportunidades de venta.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Clientes", "funcion": "Dar seguimiento a clientes con accesorios pendientes por falta de existencia hasta completar la venta o instalación.", "frecuencia": "", "tiempo": ""}, {"categoria": "Clientes", "funcion": "Elaborar y enviar cotizaciones a clientes contactados por redes sociales, teléfono y visitas de campo.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Clientes", "funcion": "Mantener comunicación postventa con el cliente para confirmar pendientes y continuidad del servicio.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Facturación", "funcion": "Facturar las ventas y servicios realizados conforme a la documentación correspondiente.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación", "funcion": "Acompañar al cliente a caja para realizar el pago y orientarlo sobre el proceso.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación", "funcion": "Llevar el estado y seguimiento de las cuentas por cobrar de los clientes asignados.", "frecuencia": "", "tiempo": ""}, {"categoria": "Facturación", "funcion": "Contactar a los clientes en sus fechas de pago y efectuar la labor de cobro correspondiente.", "frecuencia": "", "tiempo": ""}], "indicadores": [{"indicador": "Cantidad de facturas correctas", "resultado_esperado": "Lograr un ---% de facturas sin errores."}, {"indicador": "Satisfacción de clientes internos y externos", "resultado_esperado": "95% NPS positivo"}], "inversion_actividades": "100% ACCISA", "nivel_iniciativa": "Iniciativa: Media-Alta. Debe demostrar iniciativa para identificar oportunidades de venta, comprender las necesidades del cliente y brindar soluciones oportunas, aun sin supervisión directa. Asimismo, se espera que mantenga un seguimiento constante a clientes potenciales, gestione consultas de forma efectiva, impulse el cierre de ventas y promueva mejoras en la atención al cliente, contribuyendo al cumplimiento de los objetivos comerciales y al fortalecimiento de relaciones duraderas con los clientes.", "toma_decisiones": "Alta: Toma decisiones relacionadas con la atención al cliente y la gestión comercial, ofreciendo soluciones oportunas dentro de las políticas de la empresa. Prioriza oportunidades de venta, negocia alternativas comerciales, da seguimiento a cotizaciones y pedidos, resuelve incidencias de su competencia y canaliza oportunamente a la jefatura los casos que requieran autorización, contribuyendo al cumplimiento de los objetivos comerciales y a una experiencia positiva para el cliente.", "riesgos": "1. No conocer el precio o los datos de facturación, al hacer las facturaciones o conocimiento del producto.\n2. Facturar al cliente montos equivocados", "manejo_activos": "Acceso a programas de Computadora (Software, Internet, Data Crédito, entre otros)", "equipos_trabajo": "Uniforme corporativo: camisa polo. Radio. Gafete institucional", "equipos_seguridad": "Acceso al sistema ERP o sistema de ventas. Acceso a plataformas de mensajería corporativa (Teams, WhatsApp Business, etc.)", "relaciones_internas": [], "relaciones_externas": [], "condiciones_trabajo": "El puesto se desenvuelve en un ambiente de oficina. Su ubicación física es la oficina instalada en la capital, donde se encuentra el centro de operaciones. En cuanto a las condiciones ambientales en donde se desarrolla el puesto, son normales.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico Alto, El puesto requiere permanecer sentado y de pie de forma alterna durante la jornada laboral, movilizarse constantemente entre el área de ventas, recepción, bodega o taller para brindar seguimiento a clientes y coordinar entregas o instalaciones. Asimismo, demanda el uso continuo del equipo de cómputo y otros recursos tecnológicos para la gestión de cotizaciones, pedidos y registros.\nNivel de Esfuerzo Mental Alto, Requiere mantener un alto nivel de concentración para atender simultáneamente a varios clientes, identificar sus necesidades, elaborar cotizaciones, dar seguimiento a ventas y resolver consultas de manera oportuna. Además, demanda capacidad para priorizar actividades, trabajar bajo presión, cumplir metas comerciales, tomar decisiones dentro de los lineamientos establecidos y ofrecer una atención al cliente de alta calidad.", "perfil": {"edad": "20+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "2 años en puesto similar", "formacion_academica": "Graduado de nivel diversificado en Perito Contador, Bachiller en Ciencias y Letras, Bachiller en Computación, Perito en Administración o carrera afín.", "formacion_complementaria": "Diplomados o cursos en: Técnicas de ventas consultivas. Servicio y atención al cliente. Manejo de indicadores de ventas.", "conocimientos_basicos": "Conocimiento básico de accesorios para vehículos, sus características, aplicaciones y beneficios. Conocimiento del proceso de instalación y tiempos estimados de servicio (deseable).", "habilidades_especificas": "Habilidad para negociar y cerrar ventas de manera efectiva. Capacidad para resolver consultas, objeciones y reclamos de manera efectiva.", "conocimientos_informaticos": "Google Drive / OneDrive. WhatsApp Business. Microsoft Office: Avanzado. Otras: CRM (Zoho o similar)", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente", "se_requiere_vehiculo": "De preferencia sí (transporte)", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, compromiso, respeto"}, "competencias_generales": [{"competencia": "Integridad y ética profesional.", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Adaptabilidad al cambio.", "grado": "B"}, {"competencia": "Trabajo en equipo.", "grado": "A"}, {"competencia": "Proactividad", "grado": "A"}, {"competencia": "Comunicación efectiva", "grado": "A"}], "competencias_especificas": [{"competencia": "Orientación a resultados", "grado": "A"}, {"competencia": "Negociación", "grado": "A"}, {"competencia": "Cumplimiento de metas comerciales", "grado": "A"}, {"competencia": "Inteligencia emocional", "grado": "B"}, {"competencia": "Manejo de conflictos.", "grado": "A"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente Administrativo", "fecha_elaboracion": "2025-08-08", "fecha_revision": "2026-07-25", "version": "Rev. 25.07.2026 — Ref. ACCISA-005"}$json$::jsonb)
