insert into public.descripciones_roles (puesto, descripcion, requisitos, codigo, empresa, area, departamento, lugar_trabajo, jefe_inmediato, nivel_jerarquico, salario, detalle)
values ('Supervisor de Ventas y Taller', 'Bajo la supervisión de la Gerente general, supervisa y coordina la gestión comercial y operativa de Accesorios Ilimitados, de los vendedores de sala de ventas, instalaciones, taller, bodega, clientes y proveedores, para atender requerimientos, resolver reclamos y dar seguimiento a cotizaciones, pedidos, compras e instalaciones especiales.', 'Estudios universitarios avanzados (mínimo 3er año) en Administración de Empresas, Mercadotecnia, Ingeniería Industrial o Administración de Negocios. 3 años en puesto similar. Liderazgo, comunicación efectiva y asertiva, orientación al logro, capacidad para motivar y desarrollar equipos, toma de decisiones, resolución de conflictos y negociación.', 'ACCISA-004', 'ACCISA', 'Administrativo', 'Administrativo', 'Oficina principal de Accesorios Ilimitados S.A.', 'Lic. Mario Ríos', 'Administrativo / Operativo', 'Q4,050.00 Base + Comisiones', $json${"no_supervisa": "17", "posiciones_supervisa": "Supervisores de taller, vendedores y mecánicos instaladores", "funciones": [{"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Administrar, dirigir y coordinar las actividades de los asesores, incluyendo nuevos proveedores, productos y precios.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Analizar y estudiar otras líneas de mercado.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Manejar personalmente las cuentas y/o proveedores que se consideran especiales.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Definir en conjunto con Gerente de Ventas, precios y condiciones para ofertar a clientes y realizar cotizaciones", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Revisión de resultados de ventas diarias en el sistema para dar seguimiento al cumplimiento de las metas.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Programar visitas de ventas con las cuentas especiales y preparar el reporte de visitas realizadas.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Visitas a clientes para mantener fidelización y nuevas oportunidades.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Monitoreo de las actividades del sector industrial (nuevas tendencias, competencia, otros)", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Revisión de cuentas por pagar", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Mantener contacto directo con las gerencias y encargados de las distintas agencias automotrices, entre ellas Canella, Grupo Excel y Seguros Universales.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Solucionar reclamos de agencias y clientes relacionados con accesorios o instalaciones.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Revisar inventarios y realizar pedidos a fábricas.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Solucionar problemas relacionados con la operación de la empresa.", "frecuencia": "", "tiempo": ""}, {"categoria": "Ventas, Atención a Clientes y Proveedores", "funcion": "Soporte al Departamento Comercial", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Compras", "funcion": "Conseguir accesorios localmente cuando exista un requerimiento de emergencia.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Compras", "funcion": "Cotizar y buscar accesorios solicitados en negociaciones especiales.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Compras", "funcion": "Realizar compras necesarias para el personal, las instalaciones y el taller.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Análisis y Reportería", "funcion": "Reporte al Gerente General para mantenerlo informado de los avances, proyectos y logros semanales.", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Análisis y Reportería", "funcion": "Revisar y facturar las órdenes de instalaciones de agencias.", "frecuencia": "", "tiempo": ""}, {"categoria": "Análisis y Reportería", "funcion": "Evaluar resultados versus cuotas (mensual, trimestral, anual).", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Análisis y Reportería", "funcion": "Autorizar permisos o vacaciones de instaladores, jefes de taller y vendedores.", "frecuencia": "", "tiempo": ""}, {"categoria": "Análisis y Reportería", "funcion": "Presentación resultados a Junta Directiva", "frecuencia": "Diario", "tiempo": ""}, {"categoria": "Supervisión de Instalaciones", "funcion": "Supervisar instalaciones especiales en taller.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión de Instalaciones", "funcion": "Resolver conflictos en casos especiales con personal de la empresa.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión de Instalaciones", "funcion": "Dar seguimiento a dudas e instalaciones de Grupo Excel.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión de Instalaciones", "funcion": "Tomar decisiones entre las áreas de instalaciones, ventas y bodega.", "frecuencia": "", "tiempo": ""}, {"categoria": "Supervisión de Instalaciones", "funcion": "Cubrir áreas cuando sea necesario, incluyendo caja, bodega y ventas.", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "RRHH", "funcion": "Coordinar con Recursos Humanos, las contrataciones, sustituciones y reemplazo del personal a su cargo.", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "RRHH", "funcion": "Apoyar al departamento de Recursos Humanos en los procesos como: Reclutamiento (entrevista final por competencias), políticas, capacitaciones, mediciones, procesos disciplinarios. Que ayudarán a desarrollar y llevarlos al nivel que se requiere.", "frecuencia": "Eventualmente", "tiempo": ""}, {"categoria": "RRHH", "funcion": "Apoyo para coordinar las capacitaciones del personal, según sean necesarias", "frecuencia": "Eventualmente", "tiempo": ""}], "indicadores": [{"indicador": "Cantidad de facturas correctas", "resultado_esperado": "Lograr un ---% de facturas sin errores."}, {"indicador": "Satisfacción de clientes internos y externos", "resultado_esperado": "95% NPS positivo"}], "inversion_actividades": "100% ACCISA", "nivel_iniciativa": "Iniciativa: Media-Alta. Debe ser capaz de identificar situaciones inusuales o potenciales riesgos y actuar de inmediato siguiendo protocolos internos, incluso sin supervisión directa. Requiere proactividad para proponer mejoras en los procesos de control, registro y prevención de incidentes.", "toma_decisiones": "Alta: Decide acciones inmediatas en casos de riesgo evidente (por ejemplo, activar una alarma, llamar a brigadas internas o contactar a emergencias). Autoriza permisos o vacaciones de instaladores, jefes de taller y vendedores; y resuelve reclamos, conflictos y problemas relacionados con accesorios, instalaciones y la operación de la empresa.", "riesgos": "1. No conocer el precio o los datos de facturación, al hacer las facturaciones o conocimiento del producto.\n2. Facturar al cliente montos equivocados", "manejo_activos": "Acceso a programas de Computadora (Software, Internet, Data Crédito, entre otros)", "equipos_trabajo": "Uniforme corporativo: camisa polo. Laptop", "equipos_seguridad": "Acceso a programas de Computadora (Software, Internet, Data Crédito, entre otros)", "relaciones_internas": [{"departamento": "Gerencia/Gerencia General", "frecuencia": "Semanal", "proposito": "Autofacturación, reportes"}, {"departamento": "Contabilidad/Cobros", "frecuencia": "Diaria", "proposito": "Temas de facturación"}, {"departamento": "Operaciones/Bodega", "frecuencia": "Diaria", "proposito": "Temas acerca de los cortes"}, {"departamento": "Ventas/Asesores", "frecuencia": "Diaria", "proposito": "Temas de facturación"}, {"departamento": "Recepción", "frecuencia": "Diaria", "proposito": "Entrega de facturas para rutas"}], "relaciones_externas": [{"persona": "Clientes/Doctores", "frecuencia": "Diario", "proposito": "Facturas, cortes."}, {"persona": "Hospitales", "frecuencia": "Semanal", "proposito": "Requerimiento de información"}], "condiciones_trabajo": "El puesto se desenvuelve en un ambiente de oficina. Su ubicación física es la oficina instalada en la capital, donde se encuentra el centro de operaciones. En cuanto a las condiciones ambientales en donde se desarrolla el puesto, son normales.", "esfuerzo_fisico_mental": "Nivel de esfuerzo físico Alto, requiere mantenerse de pie por períodos prolongados durante los recorridos y control de accesos. Movimientos frecuentes para realizar inspecciones en diferentes áreas (caminar, subir escaleras).\nNivel de Esfuerzo Mental Alto, Necesita mantener atención constante para detectar irregularidades y situaciones de riesgo. Capacidad para resolver problemas inmediatos bajo presión, siguiendo protocolos establecidos.", "perfil": {"edad": "35+", "estado_civil": "Indiferente", "sexo": "Indiferente", "idiomas": "Español", "anios_experiencia": "3 años en puesto similar", "formacion_academica": "Estudios universitarios avanzados (mínimo 3.er año) en alguna de las siguientes carreras: Administración de Empresas, Mercadotecnia, Ingeniería Industrial, Administración de Negocios.", "formacion_complementaria": "Diplomados o cursos en: Técnicas de ventas. Liderazgo y gestión de equipos. Negociación. Servicio al cliente. Gestión de indicadores (KPIs). Coaching comercial.", "conocimientos_basicos": "Técnicas de ventas, negociación y cierre de negocios. Liderazgo y supervisión de equipos de ventas. Planificación, organización y seguimiento de actividades comerciales. Elaboración, análisis e interpretación de indicadores de gestión (KPIs).", "habilidades_especificas": "Liderazgo. Comunicación efectiva y asertiva. Orientación al logro y cumplimiento de resultados. Capacidad para motivar y desarrollar equipos de trabajo. Toma de decisiones. Resolución de conflictos y negociación. Organización y planificación.", "conocimientos_informaticos": "Google Drive / OneDrive. WhatsApp Business. Microsoft Office: Avanzado. Otras: CRM (Zoho o similar)", "sistemas_especializados": "No indispensable", "beneficios": "Medio día por cumpleaños", "se_requiere_viajar": "Eventualmente", "se_requiere_vehiculo": "Sí", "se_requiere_pasaporte": "No", "valores_actitudes": "Integridad, compromiso, respeto"}, "competencias_generales": [{"competencia": "Integridad y ética profesional.", "grado": "A"}, {"competencia": "Atención al detalle", "grado": "A"}, {"competencia": "Adaptabilidad al cambio.", "grado": "B"}, {"competencia": "Trabajo en equipo.", "grado": "A"}, {"competencia": "Proactividad", "grado": "A"}], "competencias_especificas": [{"competencia": "Capacidad de Planificación y Organización", "grado": "A"}, {"competencia": "Toma de decisiones.", "grado": "A"}, {"competencia": "Inteligencia emocional.", "grado": "A"}, {"competencia": "Orientación a resultados.", "grado": "A"}, {"competencia": "Desarrollo y formación de colaboradores (coaching).", "grado": "B"}, {"competencia": "Manejo de conflictos.", "grado": "A"}], "elaborado_por": "Gabriela Chan", "revisado_por": "Gerente Administrativo", "fecha_elaboracion": "2025-08-08", "fecha_revision": "2026-07-25", "version": "Rev. 25.07.2026 — Ref. ACCISA-004"}$json$::jsonb)
